def parse_raw(raw):
    """Parse '+HHH-LLL' tokens into list of (high, low) tuples."""
    pulses = []
    for token in raw.strip().split():
        token = token.lstrip('+')
        if '-' in token:
            h, l = token.split('-')
            pulses.append((int(h), int(l)))
    return pulses

def extract_bits(pulses, threshold=THRESHOLD, sync_us=SYNC_US):
    """
    Strip sync pulses (HIGH >= sync_us) and decode data bits.
    Returns list of (block_index, bits) for each data block between syncs.
    """
    blocks = []
    current = []

    for hi, lo in pulses:
        if hi >= sync_us:
            # sync pulse — flush current block if it has data
            if len(current) >= 8:
                blocks.append(current)
            current = []
        else:
            current.append(1 if hi >= threshold else 0)

    if len(current) >= 8:
        blocks.append(current)

    return blocks

def bits_to_hex(bits):
    """Group bits into bytes and format as hex string."""
    result = []
    for i in range(0, len(bits) - 7, 8):
        byte = 0
        for b in bits[i:i+8]:
            byte = (byte << 1) | b
        result.append(f"{byte:02X}")
    remainder = len(bits) % 8
    if remainder:
        result.append(f"(+{remainder}bits)")
    return ' '.join(result)

def most_common_block(blocks):
    """Return the most common block (majority vote across repetitions)."""
    if not blocks:
        return []
    # Use the longest block as reference length
    ref_len = max(len(b) for b in blocks)
    # Majority vote bit by bit
    result = []
    for i in range(ref_len):
        ones = sum(1 for b in blocks if i < len(b) and b[i] == 1)
        result.append(1 if ones > len(blocks) / 2 else 0)
    return result

print("=" * 60)
print("UC7070T Ceiling Fan Remote — Protocol Analysis")
print("=" * 60)

decoded = {}
for name, raw in CAPTURES.items():
    pulses = parse_raw(raw)
    blocks = extract_bits(pulses)
    voted  = most_common_block(blocks)
    decoded[name] = voted
    print(f"\n{name}: {len(blocks)} repetitions, {len(voted)} bits each")
    print(f"  HEX: {bits_to_hex(voted)}")
    print(f"  BIN: {''.join(str(b) for b in voted)}")

# Find which bit positions differ between buttons
print("\n" + "=" * 60)
print("Bit differences between commands")
print("=" * 60)

names = list(decoded.keys())
ref_bits = decoded[names[0]]
ref_len  = len(ref_bits)

# Print aligned comparison
header = f"{'Bit':>4}  " + "  ".join(f"{n:>5}" for n in names) + "  SAME?"
print(header)
for i in range(ref_len):
    vals = [decoded[n][i] if i < len(decoded[n]) else '?' for n in names]
    same = len(set(vals)) == 1
    if not same:
        row = f"{i:>4}  " + "  ".join(f"{v:>5}" for v in vals) + "   <-- DIFFERS"
        print(row)

print("\nByte-level summary:")
print(f"{'Byte':>5}  " + "  ".join(f"{n:>5}" for n in names))
for byte_i in range(ref_len // 8):
    start = byte_i * 8
    rows = []
    for n in names:
        bits = decoded[n][start:start+8]
        val  = 0
        for b in bits:
            val = (val << 1) | b
        rows.append(f"  {val:02X}")
    same = len(set(rows)) == 1
    flag = "" if same else "  <-- DIFFERS"
    print(f"  B{byte_i}:  " + "".join(rows) + flag)
